// 加载 ASTER GDEM 数据集（GEE 中对应产品）
var demCollection = ee.ImageCollection('NASA/ASTER_GED/AG100_003')
  .filterDate('2000-01-01', '2000-01-01')
  .filterBounds(ee.Geometry.BBox(108.5, 18.1, 111.0, 20.1));

// 1) 多景 DEM 镶嵌，形成连续 DEM 表面
var dem = demCollection.mosaic();

// 2) 对连续 DEM 做基础平滑，抑制局部噪声
var dem_base = dem.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.square(1)
});

// 3) 基于处理后的 DEM 生成地形阴影结果
var hillshade = ee.Terrain.hillshade(dem_base);

// 可视化参数
