// 6) 计算受损植被相关指数 B：NBR2 = (SWIR1 - SWIR2) / (SWIR1 + SWIR2)
var nbr2_num = swir1_band.subtract(swir2_band);
var nbr2_den = swir1_band.add(swir2_band);
