// =========================
// 4. 高程分带
// 0-300m   -> 1 低位带
// 300-800m -> 2 中位带
// 800m+    -> 3 高位带
// =========================
var elev_class = ee.Image(1).where(dem_clipped.gt(300), 2)
                            .where(dem_clipped.gt(800), 3);

