// 5. 坡度分级
// 0-8°   -> 1 平缓坡
// 8-20°  -> 2 起伏坡
// 20-90° -> 3 陡坡
// =========================
var slope_class = ee.Image(1).where(slope.gt(8), 2)
                             .where(slope.gt(20), 3);

// =========================
// 6. 联合编码
// 联合编码 = 高程类别 * 10 + 坡度类别
// 得到 11,12,13,21,22,23,31,32,33
