// 起伏度 = 邻域最大值 - 邻域最小值
// 使用 circle 核、radius=5，表达局部地形起伏强弱
// =========================
var focal_max = dem_mosaic.reduceNeighborhood({
  reducer: ee.Reducer.max(),
  kernel: ee.Kernel.circle(9, 'meters')
});

var focal_min = dem_mosaic.reduceNeighborhood({
