// 2: 中复杂度
// 3: 高复杂度
// =========================
var complexity = combined_class.where(combined_class.eq(11), 1)
    .where(combined_class.eq(12).or(combined_class.eq(13))
        .or(combined_class.eq(21)).or(combined_class.eq(22))
        .or(combined_class.eq(31)), 2)
    .where(combined_class.eq(23).or(combined_class.eq(32))
        .or(combined_class.eq(33)), 3);

