var dem = ee.Image('JAXA/ALOS/AW3D30_V1_2').select('DSM');

// =========================
// 2. 构建小/中/大尺度 DEM
// 思路：先对 DEM 做不同尺度平滑，再分别计算 TRI
// 这样 TRI 本身仍是局部崎岖度，但其作用尺度不同
// =========================
// 小尺度：基本保持原始地形细节
var dem_small = dem.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.circle(1)
});

// 中尺度：适度平滑
var dem_medium = dem.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.circle(3)
});

// 大尺度：更强平滑
var dem_large = dem.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.circle(7)
});

// =========================
// 3. 分别计算小/中/大尺度粗糙度（TRI）
// GEE 使用 Terrain.roughness 计算 TRI
// =========================
var tri_small = ee.Terrain.roughness(dem_small);
var tri_medium = ee.Terrain.roughness(dem_medium);
var tri_large = ee.Terrain.roughness(dem_large);

// =========================
// 4. 对三组粗糙度结果分别分级
// 1 = 低粗糙
// 2 = 中粗糙
// 3 = 高粗糙
//
// 大尺度 DEM 已经过平滑，因此 TRI 阈值随尺度变大而降低
// =========================
var small_rules = [
    (0.0, 8.0, 1.0),
    (8.0, 20.0, 2.0),
    (20.0, 5000.0, 3.0)
];

var medium_rules = [
    (0.0, 5.0, 1.0),
    (5.0, 12.0, 2.0),
    (12.0, 5000.0, 3.0)
];

var large_rules = [
    (0.0, 3.0, 1.0),
    (3.0, 8.0, 2.0),
    (8.0, 5000.0, 3.0)
];

var tri_small_class = tri_small.where(tri_small.gte(0).and(tri_small.lt(8)), 1)
    .where(tri_small.gte(8).and(tri_small.lt(20)), 2)
    .where(tri_small.gte(20), 3);

var tri_medium_class = tri_medium.where(tri_medium.gte(0).and(tri_medium.lt(5)), 1)
    .where(tri_medium.gte(5).and(tri_medium.lt(12)), 2)
    .where(tri_medium.gte(12), 3);

var tri_large_class = tri_large.where(tri_large.gte(0).and(tri_large.lt(3)), 1)
    .where(tri_large.gte(3).and(tri_large.lt(8)), 2)
    .where(tri_large.gte(8), 3);

// =========================
// 5. 各尺度高粗糙候选区提取
// 0 = 非高粗糙
// 1 = 高粗糙
// =========================
var small_high = tri_small_class.eq(3);
var medium_high = tri_medium_class.eq(3);
var large_high = tri_large_class.eq(3);

// =========================
// 6. 统计高粗糙出现次数
// high_count = 0,1,2,3
// 同时计算三尺度等级总和（3~9）
// =========================
var high_count = small_high.add(medium_high).add(large_high);
var roughness_sum = tri_small_class.add(tri_medium_class).add(tri_large_class);

// =========================
// 7. 构建综合复杂度分数
// combined_score = high_count * 10 + roughness_sum
//
// 设计思想：
// - 多尺度高粗糙出现次数越多，复杂度越高
// - 即便没有达到“高粗糙”，如果三个尺度总和偏高，也可进入中复杂度
// =========================
var high_count_x10 = high_count.multiply(10);
var combined_score = high_count_x10.add(roughness_sum);

// =========================
// 8. 归并为综合复杂度等级
// 1 = 低复杂度
// 2 = 中复杂度
// 3 = 高复杂度
//
// 规则解释：
// - high_count = 0，且总和较低 -> 低复杂度
// - high_count = 0，但总和偏高；或 high_count = 1 -> 中复杂度
// - high_count >= 2 -> 高复杂度
// =========================
var complexity = combined_score.where(combined_score.gte(3).and(combined_score.lt(5)), 1)
    .where(combined_score.gte(5).and(combined_score.lt(7)), 2)
    .where(combined_score.gte(15).and(combined_score.lt(20)), 2)
    .where(combined_score.gte(25).and(combined_score.lt(40)), 3);

// =========================
// 9. 轻量去碎斑
// =========================
var complexity_smooth = complexity.reduceNeighborhood({
  reducer: ee.Reducer.mode(),
  kernel: ee.Kernel.circle(1)
});

