        '#fdae61',  // 中复杂度
        '#d73027'   // 高复杂度
    ]
};

Map.addLayer(tri_small_class, roughness_vis, '小尺度粗糙度结果');
Map.addLayer(tri_medium_class, roughness_vis, '中尺度粗糙度结果');
Map.addLayer(tri_large_class, roughness_vis, '大尺度粗糙度结果');
