// 使用 GEE 的 zonal histogram 方法近似地理探测器
// 计算各因子分层的 LST 方差分解
function geoDetectorApprox(lst, factor, factorClass, minVal, maxVal) {
  // 掩膜有效值范围
  var validLst = lst.updateMask(lst.gte(minVal)).updateMask(lst.lte(maxVal));

  // 总体方差
  var totalMean = validLst.reduceRegion({
    reducer: ee.Reducer.mean(),
    scale: 30,
    maxPixels: 1e9
  }).getNumber('ST_B10');

  var totalVar = validLst.subtract(totalMean).pow(2).reduceRegion({
    reducer: ee.Reducer.mean(),
    scale: 30,
    maxPixels: 1e9
  }).getNumber('ST_B10');

  // 分层方差
  var classMeans = factorClass.reduceRegions({
    collection: factorClass.selfMask().reduceToVectors({
      geometry: factorClass.geometry(),
      scale: 30,
      geometryType: 'polygon',
      eightConnected: false
    }),
    reducer: ee.Reducer.mean(),
    scale: 30
  });

  // 计算 q 统计量（简化版）
  var qValue = ee.Number(1).subtract(
    classMeans.aggregate_sum('sum') 
  ).divide(totalVar);

  return qValue;
}

