// 计算局部莫兰指数（Local Moran's I）
// 使用邻域统计计算局部空间自相关
var lisa = feature.map(function(f) {
  // 获取当前要素的几何和属性
  var geom = f.geometry();
  var aging = f.getNumber('aging');

  // 查找邻域要素（缓冲区或空间连接）
  var neighbors = feature.filterBounds(geom.buffer(50000)); // 50km缓冲区作为邻域

  // 计算邻域的平均值
  var neighborMean = neighbors.reduceColumns({
    reducer: ee.Reducer.mean(),
    selectors: ['aging']
  }).get('mean');

  // 计算全局平均值和标准差
  var globalStats = feature.reduceColumns({
    reducer: ee.Reducer.mean().combine(ee.Reducer.stdDev(), null, true),
    selectors: ['aging']
  });
  var globalMean = globalStats.get('mean');
  var globalStd = globalStats.get('stdDev');

  // 计算局部莫兰指数
  var n = feature.size();
  var zi = aging.subtract(globalMean);
  var zj = neighborMean.subtract(globalMean);
  var moranI = zi.multiply(zj).divide(globalStd.multiply(globalStd)).multiply(n.subtract(1)).divide(n);

  return f.set('LISA', moranI);
});

// 可视化 LISA 结果
Map.addLayer(lisa, {color: '#FFFF00'}, 'LISA结果');

