// Load Landsat 8 TOA reflectance image
var lc08 = ee.Image('LANDSAT/LC08/C02/T1_TOA/LC08_122038_20150930');

// Select green and NIR bands
var green = lc08.select('B3');
var nir = lc08.select('B5');

// Calculate NDWI: (Green - NIR) / (Green + NIR)
var numerator = green.subtract(nir);
var denominator = green.add(nir);
var ndwi = numerator.divide(denominator);

// Visualization parameters
var vis_params = {
  min: -1,
  max: 1,
  palette: ['blue', 'lightblue', 'green', 'yellow', 'red']
};

// Add NDWI layer to map
