// Load Landsat 8 TOA reflectance image
var lc08 = ee.Image('LANDSAT/LC08/C02/T1_TOA/LC08_122038_20150930');

// Calculate NDWI using Green and NIR bands
var ndwi = lc08.normalizedDifference(['B3', 'B5']).multiply(100.0);

// Binarize NDWI: water pixels where NDWI > 10
var Ndwi_binarization = ndwi.gt(10);

// Apply focal median filter with 1-pixel square kernel
var Ndwi_binarization_Median = Ndwi_binarization.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: ee.Kernel.square(1)
});

// Visualization parameters
var vis_params = {min: 0, max: 1, palette: ['black', '#87CEFA']};

// Add layer to map
Map.addLayer(Ndwi_binarization_Median, vis_params, 'water');

// Center map on the area of interest
Map.setCenter(115.74080156644999, 31.7318082104, 11);

// Load Landsat 8 TOA reflectance image
var lc08 = ee.Image('LANDSAT/LC08/C02/T1_TOA/LC08_122038_20150801');

// Convert to float
var lc08_float = lc08.toFloat();

// Select bands B6 (SWIR1) and B2 (Blue)
var b6 = lc08_float.select('B6');
var b2 = lc08_float.select('B2');

