// 地理探测器因子检测 - 需要手动实现
// 这里展示一个简化的示例，实际需要根据数据计算 q 统计量
function geoFactorDetector(featureCollection, dependentVar, independentVars) {
  // 获取因变量和自变量
  var dependent = featureCollection.select(dependentVar);
  var independents = featureCollection.select(independentVars);

  // 计算总体方差
  var totalVariance = dependent.reduceColumns(ee.Reducer.variance(), [dependentVar]).get('variance');

  // 对每个自变量计算分层方差
  var results = independentVars.map(function(varName) {
    // 按自变量分层
    var strata = featureCollection.reduceColumns(ee.Reducer.group(1, ee.Reducer.variance()), [varName, dependentVar]);

    // 计算层内方差加权和
    var withinVariance = ee.List(strata.get('groups')).map(function(group) {
      var g = ee.Dictionary(group);
      var count = ee.Number(g.get('count'));
      var variance = ee.Number(g.get('variance'));
      return count.multiply(variance);
    }).reduce(ee.Reducer.sum());

    // 计算 q 统计量
    var q = ee.Number(1).subtract(withinVariance.divide(totalVariance.multiply(featureCollection.size())));

    return ee.Feature(null, {variable: varName, q_statistic: q});
  });

  return ee.FeatureCollection(results);
}

