// 注意：GEE 中没有直接对应的 ACF 处理函数，需要手动实现
// 这里使用 reduceRegion 和 ee.Reducer 来计算自相关
var acfResult = feature.map(function(f) {
  var values = ee.List(f.get('aging')); // 假设 aging 字段是数组
  var n = values.size();

  // 计算滞后 k 的自相关系数
  var acf = ee.List.sequence(0, 10).map(function(k) {
    var lag = ee.Number(k);
    var mean = values.reduce(ee.Reducer.mean());

    // 计算分子和分母
    var numerator = ee.List.sequence(0, n.subtract(lag).subtract(1)).map(function(i) {
      var iNum = ee.Number(i);
      var v1 = values.get(iNum);
      var v2 = values.get(iNum.add(lag));
      return ee.Number(v1).subtract(mean).multiply(ee.Number(v2).subtract(mean));
    }).reduce(ee.Reducer.sum());

    var denominator = ee.List.sequence(0, n.subtract(1)).map(function(i) {
      var iNum = ee.Number(i);
      var v = values.get(iNum);
      return ee.Number(v).subtract(mean).pow(2);
    }).reduce(ee.Reducer.sum());

    return numerator.divide(denominator);
  });

  return f.set('acf', acf);
});

