  var diff = ee.Number(f.get('aging')).subtract(y_mean);
  return diff.multiply(diff);
}).reduceColumns(ee.Reducer.sum(), ['sum']).get('sum');

// 3. 对每个自变量进行分层（离散化）
// 这里使用简单的等间距分层，实际应用中可能需要更复杂的方法
var layers = x_vars.map(function(x) {
  var name = x.bandNames().get(0);
  var min = x.reduceColumns(ee.Reducer.min(), [name]).get('min');
  var max = x.reduceColumns(ee.Reducer.max(), [name]).get('max');
  var range = ee.Number(max).subtract(min);

  // 分为 5 层
  return feature.map(function(f) {
    var val = ee.Number(f.get(name));
    var layer = val.subtract(min).divide(range).multiply(5).floor().min(4).max(0);
    return f.set(name + '_layer', layer);
  });
});

// 4. 计算每个分层的方差和
var layer_vars = layers.map(function(layer_fc) {
  var name = layer_fc.first().propertyNames().filter(ee.Filter.stringStartsWith('item', '_layer')).get(0);
  var layer_names = layer_fc.aggregate_array(name).distinct();

  var total_within_var = layer_names.map(function(layer) {
    var subset = layer_fc.filter(ee.Filter.eq(name, layer));
    var subset_mean = subset.reduceColumns(ee.Reducer.mean(), ['aging']).get('mean');
    var subset_var = subset.map(function(f) {
      var diff = ee.Number(f.get('aging')).subtract(subset_mean);
      return diff.multiply(diff);
    }).reduceColumns(ee.Reducer.sum(), ['sum']).get('sum');
    return subset_var;
  }).reduce(ee.Reducer.sum());

  return total_within_var;
});

// 5. 计算 q 统计量
var q_values = layer_vars.map(function(within_var) {
  return ee.Number(1).subtract(ee.Number(within_var).divide(y_var));
});

// 打印结果
print('地理探测器 q 值：', q_values);

